insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M1-1', 'lesson-coordinate-city', 'mc', 'koordinat', 'Titik (−3, 5) terletak di ...', '{"options": ["Kuadran I", "Kuadran II", "Kuadran III", "Kuadran IV"], "hint": "Lihat tanda x dan y: x negatif, y positif."}'::jsonb, '1'::jsonb, 'x = −3 (kiri) dan y = 5 (atas). Pola (−, +) adalah Kuadran II.', 0) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M1-2', 'lesson-coordinate-city', 'point', 'koordinat', 'Klik letak titik (4, −2) pada bidang koordinat.', '{"range": 6, "hint": "Mulai dari O: 4 langkah ke kanan, lalu 2 langkah ke bawah."}'::jsonb, '[4, -2]'::jsonb, 'x = 4 berarti ke kanan 4 satuan, y = −2 berarti ke bawah 2 satuan. Titiknya di Kuadran IV.', 1) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M1-3', 'lesson-coordinate-city', 'tf', 'koordinat', 'Titik (0, 6) terletak di Kuadran I.', '{"hint": "Nilai x-nya 0. Di mana letak titik yang x-nya 0?"}'::jsonb, 'false'::jsonb, 'Karena x = 0, titik (0, 6) berada tepat di sumbu Y, sehingga tidak termasuk kuadran mana pun.', 2) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M2-1', 'lesson-point-detective', 'tf', 'titik-garis', 'Melalui dua titik yang berbeda hanya dapat dibuat tepat satu garis lurus.', '{"hint": "Coba bayangkan menarik benang lurus di antara dua paku."}'::jsonb, 'true'::jsonb, 'Benar. Dua titik berbeda selalu menentukan tepat satu garis lurus.', 0) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M2-2', 'lesson-point-detective', 'mc', 'titik-garis', 'Titik manakah yang terletak pada garis y = 2x + 1?', '{"options": ["(1, 2)", "(2, 5)", "(3, 6)", "(0, 2)"], "hint": "Substitusikan nilai x setiap titik ke 2x + 1, lalu bandingkan dengan y-nya."}'::jsonb, '1'::jsonb, 'Untuk (2, 5): 2(2) + 1 = 5, sama dengan y. Titik lain tidak memenuhi, misalnya (1, 2): 2(1) + 1 = 3 ≠ 2.', 1) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M2-3', 'lesson-point-detective', 'mc', 'titik-garis', 'Garis yang melalui titik (2, 1) dan (2, 5) adalah garis ...', '{"options": ["horizontal", "vertikal", "miring naik", "miring turun"], "hint": "Perhatikan: nilai x kedua titik sama."}'::jsonb, '1'::jsonb, 'Kedua titik memiliki x = 2, jadi garisnya tegak (vertikal) dengan persamaan x = 2.', 2) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M3-1', 'lesson-gradient-mountain', 'num', 'gradien', 'Gradien garis yang melalui (1, 3) dan (3, 7) adalah ...', '{"hint": "m = (y₂ − y₁)/(x₂ − x₁)."}'::jsonb, '"2"'::jsonb, 'm = (7 − 3)/(3 − 1) = 4/2 = 2.', 0) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M3-2', 'lesson-gradient-mountain', 'mc', 'gradien', 'Garis yang turun dari kiri ke kanan memiliki gradien ...', '{"options": ["positif", "negatif", "nol", "tidak terdefinisi"], "hint": "Saat x bertambah, y justru berkurang."}'::jsonb, '1'::jsonb, 'Jika y berkurang saat x bertambah, Δy negatif dan Δx positif, sehingga m negatif.', 1) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M3-3', 'lesson-gradient-mountain', 'num', 'gradien', 'Gradien garis yang melalui (−2, 5) dan (4, 2) adalah ... (tulis dalam pecahan, mis. −1/3)', '{"hint": "Hati-hati dengan x₁ = −2: x₂ − x₁ = 4 − (−2)."}'::jsonb, '"-1/2"'::jsonb, 'm = (2 − 5)/(4 − (−2)) = −3/6 = −1/2.', 2) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M4-1', 'lesson-equation-factory', 'mc', 'persamaan', 'Gradien dan titik potong sumbu Y dari garis y = −3x + 5 adalah ...', '{"options": ["m = −3 dan (0, 5)", "m = 5 dan (0, −3)", "m = 3 dan (0, 5)", "m = −3 dan (5, 0)"], "hint": "Pada y = mx + c, m adalah koefisien x dan titik potong sumbu Y adalah (0, c)."}'::jsonb, '0'::jsonb, 'Koefisien x adalah −3, jadi m = −3. Konstantanya 5, jadi titik potong sumbu Y adalah (0, 5).', 0) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M4-2', 'lesson-equation-factory', 'num', 'persamaan', 'Gradien garis 4x + 2y − 6 = 0 adalah ...', '{"hint": "Gunakan m = −a/b, atau ubah dulu ke bentuk y = mx + c."}'::jsonb, '"-2"'::jsonb, 'a = 4, b = 2, sehingga m = −4/2 = −2. Cek: 2y = −4x + 6 → y = −2x + 3.', 1) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M4-3', 'lesson-equation-factory', 'tf', 'persamaan', 'Grafik y = 2x melalui titik pusat (0, 0).', '{"hint": "Substitusikan x = 0."}'::jsonb, 'true'::jsonb, 'x = 0 → y = 2(0) = 0, jadi (0, 0) terletak pada garis. Persamaan y = mx selalu melalui titik pusat.', 2) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M5-1', 'lesson-line-constructor', 'line', 'menentukan', 'Tentukan persamaan garis bergradien 2 yang melalui titik (1, 4).', '{"hint": "Gunakan y − y₁ = m(x − x₁) lalu sederhanakan."}'::jsonb, '{"m": "2", "c": "2"}'::jsonb, 'y − 4 = 2(x − 1) → y − 4 = 2x − 2 → y = 2x + 2.', 0) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M5-2', 'lesson-line-constructor', 'line', 'menentukan', 'Tentukan persamaan garis yang melalui (0, −1) dan (2, 5).', '{"hint": "Hitung gradien dulu. Titik (0, −1) adalah titik potong sumbu Y!"}'::jsonb, '{"m": "3", "c": "-1"}'::jsonb, 'm = (5 − (−1))/(2 − 0) = 6/2 = 3. Garis memotong sumbu Y di (0, −1), jadi c = −1. y = 3x − 1.', 1) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M5-3', 'lesson-line-constructor', 'mc', 'menentukan', 'Persamaan garis yang melalui titik pusat dengan gradien −4 adalah ...', '{"options": ["y = −4x", "y = x − 4", "y = −4", "y = 4x"], "hint": "Garis melalui titik pusat berbentuk y = mx."}'::jsonb, '0'::jsonb, 'Melalui O(0, 0) berarti c = 0, sehingga y = −4x.', 2) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M6-1', 'lesson-parallel-perpendicular', 'mc', 'hubungan', 'Garis yang sejajar dengan y = 3x − 2 adalah ...', '{"options": ["y = 3x + 5", "y = −3x − 2", "y = (1/3)x + 1", "y = −(1/3)x"], "hint": "Garis sejajar memiliki gradien yang sama."}'::jsonb, '0'::jsonb, 'Gradien y = 3x − 2 adalah 3. Hanya y = 3x + 5 yang gradiennya juga 3.', 0) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M6-2', 'lesson-parallel-perpendicular', 'num', 'hubungan', 'Gradien garis yang tegak lurus dengan garis bergradien 4 adalah ...', '{"hint": "m₁ × m₂ = −1, jadi m₂ = −1/m₁."}'::jsonb, '"-1/4"'::jsonb, 'm₂ = −1/4, karena 4 × (−1/4) = −1.', 1) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M6-3', 'lesson-parallel-perpendicular', 'line', 'hubungan', 'Tentukan persamaan garis yang melalui (0, 2) dan tegak lurus dengan y = −x + 7.', '{"hint": "Gradien y = −x + 7 adalah −1. Negatif kebalikannya berapa?"}'::jsonb, '{"m": "1", "c": "2"}'::jsonb, 'm₁ = −1 → m₂ = −1/(−1) = 1. Garis memotong sumbu Y di (0, 2), jadi y = x + 2.', 2) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M7-1', 'lesson-real-life', 'num', 'kehidupan', 'Sewa sepeda: Rp5.000 ditambah Rp4.000 per jam. Berapa rupiah biaya sewa selama 3 jam? (tulis angkanya saja)', '{"hint": "Model: y = 4.000x + 5.000."}'::jsonb, '"17000"'::jsonb, 'y = 4.000(3) + 5.000 = 12.000 + 5.000 = 17.000. Jadi biayanya Rp17.000.', 0) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M7-2', 'lesson-real-life', 'mc', 'kehidupan', 'Pada model biaya y = 3.000x + 7.000 (x = banyak barang), angka 3.000 menyatakan ...', '{"options": ["biaya tambahan untuk setiap 1 barang", "biaya awal sebelum membeli", "total biaya", "banyak barang yang dibeli"], "hint": "3.000 adalah gradien, yaitu laju perubahan."}'::jsonb, '0'::jsonb, 'Gradien 3.000 berarti setiap tambah 1 barang, biaya naik Rp3.000. Angka 7.000 adalah biaya awal.', 1) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('M7-3', 'lesson-real-life', 'num', 'kehidupan', 'Tinggi air di bak mula-mula 10 cm dan naik 2 cm setiap menit. Setelah berapa menit tinggi air menjadi 30 cm?', '{"hint": "Susun y = 2x + 10, lalu cari x saat y = 30."}'::jsonb, '"10"'::jsonb, '30 = 2x + 10 → 2x = 20 → x = 10 menit.', 2) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T1-01', 'training-1', 'mc', 'koordinat', 'Sumbu mendatar pada bidang Kartesius disebut ...', '{"options": ["sumbu X", "sumbu Y", "titik asal", "kuadran"], "hint": "Sumbu ini berisi nilai absis."}'::jsonb, '0'::jsonb, 'Sumbu mendatar adalah sumbu X; sumbu tegak adalah sumbu Y.', 0) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
