insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T1-03', 'training-1', 'point', 'koordinat', 'Klik letak titik B(3, −5).', '{"range": 6, "hint": "Geser mendatar dulu (x), baru tegak (y)."}'::jsonb, '[3, -5]'::jsonb, '3 langkah ke kanan lalu 5 langkah ke bawah. B berada di Kuadran IV.', 2) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
