insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T1-05', 'training-1', 'tf', 'koordinat', 'Koordinat (3, 2) dan (2, 3) menunjukkan titik yang sama.', '{"hint": "Apakah urutan dalam pasangan berurutan penting?"}'::jsonb, 'false'::jsonb, 'Salah. (3, 2) berarti 3 ke kanan dan 2 ke atas, sedangkan (2, 3) berarti 2 ke kanan dan 3 ke atas. Urutan sangat penting.', 4) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T1-06', 'training-1', 'mc', 'koordinat', 'Perhatikan grafik. Koordinat titik P adalah ...', '{"options": ["(−2, 4)", "(4, −2)", "(2, 4)", "(−2, −4)"], "graph": {"range": 6, "points": [{"x": -2, "y": 4, "label": "P"}]}, "hint": "Baca dulu posisi mendatarnya (x), lalu posisi tegaknya (y)."}'::jsonb, '0'::jsonb, 'P berada 2 satuan di kiri sumbu Y (x = −2) dan 4 satuan di atas sumbu X (y = 4).', 5) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
