insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T1-11', 'training-1', 'tf', 'gradien', 'Garis vertikal memiliki gradien nol.', '{"hint": "Pada garis vertikal, berapa nilai Δx?"}'::jsonb, 'false'::jsonb, 'Salah. Garis vertikal memiliki Δx = 0, dan pembagian dengan nol tidak terdefinisi. Yang gradiennya nol adalah garis horizontal.', 10) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
