insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T2-01', 'training-2', 'num', 'gradien', 'Gradien garis yang melalui A(2, 1) dan B(6, 9) adalah ...', '{"hint": "m = (y₂ − y₁)/(x₂ − x₁)."}'::jsonb, '"2"'::jsonb, 'm = (9 − 1)/(6 − 2) = 8/4 = 2.', 0) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T2-02', 'training-2', 'num', 'gradien', 'Gradien garis yang melalui (−1, 4) dan (3, −4) adalah ...', '{"hint": "Perhatikan tanda negatif pada y₂ dan x₁."}'::jsonb, '"-2"'::jsonb, 'm = (−4 − 4)/(3 − (−1)) = −8/4 = −2.', 1) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T2-03', 'training-2', 'num', 'gradien', 'Gradien garis yang melalui (−3, 2) dan (3, 5) adalah ... (boleh pecahan)', '{"hint": "Δy = 5 − 2, Δx = 3 − (−3)."}'::jsonb, '"1/2"'::jsonb, 'm = (5 − 2)/(3 − (−3)) = 3/6 = 1/2.', 2) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T2-04', 'training-2', 'mc', 'persamaan', 'Garis y = 5x − 3 memotong sumbu Y di titik ...', '{"options": ["(0, −3)", "(0, 5)", "(−3, 0)", "(3/5, 0)"], "hint": "Titik potong sumbu Y terjadi saat x = 0."}'::jsonb, '0'::jsonb, 'x = 0 → y = 5(0) − 3 = −3, jadi titiknya (0, −3). Titik (3/5, 0) adalah titik potong sumbu X.', 3) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T2-05', 'training-2', 'num', 'persamaan', 'Garis y = 2x − 6 memotong sumbu X di titik (a, 0). Nilai a adalah ...', '{"hint": "Titik potong sumbu X terjadi saat y = 0."}'::jsonb, '"3"'::jsonb, '0 = 2x − 6 → 2x = 6 → x = 3. Titiknya (3, 0).', 4) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T2-06', 'training-2', 'num', 'gradien', 'Gradien garis 3x − 6y + 12 = 0 adalah ...', '{"hint": "m = −a/b dengan a = 3 dan b = −6."}'::jsonb, '"1/2"'::jsonb, 'm = −3/(−6) = 1/2. Cek: 6y = 3x + 12 → y = (1/2)x + 2.', 5) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T2-07', 'training-2', 'mc', 'grafik', 'Perhatikan grafik. Gradien garis tersebut adalah ...', '{"options": ["−1", "1", "2", "−2"], "graph": {"range": 6, "lines": [{"m": -1, "c": 2}], "points": [{"x": 0, "y": 2, "label": "(0, 2)"}, {"x": 2, "y": 0, "label": "(2, 0)"}]}, "hint": "Gunakan dua titik yang ditandai: (0, 2) dan (2, 0)."}'::jsonb, '0'::jsonb, 'm = (0 − 2)/(2 − 0) = −2/2 = −1. Garisnya turun, jadi gradiennya negatif.', 6) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T2-08', 'training-2', 'mc', 'grafik', 'Perhatikan grafik. Persamaan garis tersebut adalah ...', '{"options": ["y = 2x − 1", "y = x − 1", "y = −2x − 1", "y = 2x + 1"], "graph": {"range": 6, "lines": [{"m": 2, "c": -1}], "points": [{"x": 0, "y": -1, "label": "(0, −1)"}, {"x": 2, "y": 3, "label": "(2, 3)"}]}, "hint": "Cari c dari titik potong sumbu Y, lalu hitung m dari dua titik."}'::jsonb, '0'::jsonb, 'Titik potong sumbu Y (0, −1) → c = −1. m = (3 − (−1))/(2 − 0) = 4/2 = 2. Jadi y = 2x − 1.', 7) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T2-09', 'training-2', 'tf', 'gradien', 'Garis y = −4 memiliki gradien 0.', '{"hint": "y = −4 bisa ditulis y = 0x − 4."}'::jsonb, 'true'::jsonb, 'Benar. y = −4 adalah garis horizontal; koefisien x-nya 0.', 8) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T2-10', 'training-2', 'num', 'grafik', 'Perhatikan grafik. Garis memotong sumbu Y di titik (0, c). Nilai c adalah ...', '{"graph": {"range": 6, "lines": [{"m": -2, "c": 3}]}, "hint": "Lihat di mana garis menyentuh sumbu tegak (sumbu Y)."}'::jsonb, '"3"'::jsonb, 'Garis memotong sumbu Y di (0, 3), jadi c = 3. Persamaannya y = −2x + 3.', 9) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T2-11', 'training-2', 'line', 'persamaan', 'Lengkapi persamaan garis bergradien −3 yang memotong sumbu Y di (0, 4).', '{"hint": "Gunakan y = mx + c secara langsung."}'::jsonb, '{"m": "-3", "c": "4"}'::jsonb, 'm = −3 dan c = 4, jadi y = −3x + 4.', 10) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T2-12', 'training-2', 'mc', 'gradien', 'Garis manakah yang paling curam?', '{"options": ["y = x + 1", "y = −4x + 2", "y = 2x", "y = (1/2)x + 5"], "hint": "Bandingkan nilai mutlak gradiennya, bukan tandanya."}'::jsonb, '1'::jsonb, 'Nilai mutlak gradiennya: 1, 4, 2, dan 1/2. Yang terbesar adalah |−4| = 4, jadi y = −4x + 2 paling curam (walaupun arahnya turun).', 11) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T3-01', 'training-3', 'line', 'menentukan', 'Tentukan persamaan garis yang melalui (2, 3) dan (4, 7).', '{"hint": "Hitung m, lalu gunakan y − y₁ = m(x − x₁)."}'::jsonb, '{"m": "2", "c": "-1"}'::jsonb, 'm = (7 − 3)/(4 − 2) = 2. y − 3 = 2(x − 2) → y = 2x − 1.', 0) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T3-02', 'training-3', 'line', 'menentukan', 'Tentukan persamaan garis bergradien −1/2 yang melalui (4, 1).', '{"hint": "y − 1 = −(1/2)(x − 4)."}'::jsonb, '{"m": "-1/2", "c": "3"}'::jsonb, 'y − 1 = −(1/2)(x − 4) → y − 1 = −(1/2)x + 2 → y = −(1/2)x + 3.', 1) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T3-03', 'training-3', 'line', 'menentukan', 'Tentukan persamaan garis yang melalui (−1, 5) dan (3, −3).', '{"hint": "Δx = 3 − (−1) = 4."}'::jsonb, '{"m": "-2", "c": "3"}'::jsonb, 'm = (−3 − 5)/(3 − (−1)) = −8/4 = −2. y − 5 = −2(x + 1) → y = −2x + 3.', 2) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T3-04', 'training-3', 'line', 'hubungan', 'Tentukan persamaan garis yang sejajar dengan y = 4x − 1 dan melalui (1, 6).', '{"hint": "Sejajar berarti gradiennya sama."}'::jsonb, '{"m": "4", "c": "2"}'::jsonb, 'm = 4. y − 6 = 4(x − 1) → y = 4x + 2.', 3) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T3-05', 'training-3', 'line', 'hubungan', 'Tentukan persamaan garis yang tegak lurus dengan 2x + 3y − 6 = 0 dan melalui (2, 0).', '{"hint": "Gradien 2x + 3y − 6 = 0 adalah −2/3. Negatif kebalikannya?"}'::jsonb, '{"m": "3/2", "c": "-3"}'::jsonb, 'm₁ = −2/3 → m₂ = 3/2. y − 0 = (3/2)(x − 2) → y = (3/2)x − 3.', 4) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T3-06', 'training-3', 'match', 'hubungan', 'Pasangkan garis-garis yang SEJAJAR (klik dua garis untuk membuat satu pasangan).', '{"items": ["y = 2x + 1", "y = −3x", "y = (1/2)x − 2", "y = 2x − 5", "y = −3x + 4", "y = (1/2)x + 3"], "hint": "Garis sejajar memiliki gradien (koefisien x) yang sama."}'::jsonb, '[[0, 3], [1, 4], [2, 5]]'::jsonb, 'Gradien 2: y = 2x + 1 dan y = 2x − 5. Gradien −3: y = −3x dan y = −3x + 4. Gradien 1/2: y = (1/2)x − 2 dan y = (1/2)x + 3.', 5) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T3-07', 'training-3', 'mc', 'hubungan', 'Hubungan garis y = 3x + 2 dan x + 3y − 9 = 0 adalah ...', '{"options": ["tegak lurus", "sejajar", "berimpit", "berpotongan tidak tegak lurus"], "hint": "Cari gradien garis kedua dengan m = −a/b."}'::jsonb, '0'::jsonb, 'm₁ = 3 dan m₂ = −1/3. m₁ × m₂ = 3 × (−1/3) = −1, jadi kedua garis tegak lurus.', 6) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T3-08', 'training-3', 'num', 'kehidupan', 'Biaya cetak foto Rp2.000 per lembar ditambah biaya admin Rp5.000. Jika total biaya Rp45.000, berapa lembar foto yang dicetak?', '{"hint": "45.000 = 2.000x + 5.000."}'::jsonb, '"20"'::jsonb, '2.000x = 45.000 − 5.000 = 40.000 → x = 20 lembar.', 7) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T3-09', 'training-3', 'line', 'kehidupan', 'Suhu air yang dipanaskan naik secara linear: menit ke-0 suhunya 25°C dan menit ke-4 suhunya 45°C. Tulis persamaan suhu y terhadap waktu x.', '{"hint": "Dua titik: (0, 25) dan (4, 45)."}'::jsonb, '{"m": "5", "c": "25"}'::jsonb, 'm = (45 − 25)/(4 − 0) = 5 °C per menit, c = 25 (suhu awal). y = 5x + 25.', 8) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T3-10', 'training-3', 'num', 'kehidupan', 'Taksi A: Rp7.000 + Rp4.000/km. Taksi B: Rp10.000 + Rp3.500/km. Pada jarak berapa km biaya keduanya sama?', '{"hint": "Samakan kedua persamaan."}'::jsonb, '"6"'::jsonb, '7.000 + 4.000x = 10.000 + 3.500x → 500x = 3.000 → x = 6 km.', 9) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T3-11', 'training-3', 'tf', 'hubungan', 'Garis y = 2x + 3 dan 4x − 2y + 6 = 0 adalah dua garis sejajar yang berbeda.', '{"hint": "Ubah persamaan kedua ke bentuk y = mx + c, lalu bandingkan m dan c-nya."}'::jsonb, 'false'::jsonb, 'Salah. 4x − 2y + 6 = 0 → 2y = 4x + 6 → y = 2x + 3. Gradien dan konstantanya sama, jadi kedua garis BERIMPIT (garis yang sama), bukan sejajar berbeda.', 10) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('T3-12', 'training-3', 'match', 'hubungan', 'Pasangkan garis-garis yang saling TEGAK LURUS.', '{"items": ["y = 2x", "y = −3x + 1", "y = x + 4", "y = −(1/2)x + 2", "y = (1/3)x − 1", "y = −x"], "hint": "Cari pasangan yang hasil kali gradiennya −1."}'::jsonb, '[[0, 3], [1, 4], [2, 5]]'::jsonb, '2 × (−1/2) = −1, −3 × (1/3) = −1, dan 1 × (−1) = −1.', 11) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F01', 'final-challenge', 'mc', 'koordinat', 'Titik (4, −7) terletak di ...', '{"options": ["Kuadran I", "Kuadran II", "Kuadran III", "Kuadran IV"]}'::jsonb, '3'::jsonb, 'x positif dan y negatif → (+, −) → Kuadran IV.', 0) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F02', 'final-challenge', 'point', 'koordinat', 'Tentukan letak titik (−3, −4) pada bidang koordinat.', '{"range": 6}'::jsonb, '[-3, -4]'::jsonb, '3 langkah ke kiri dan 4 langkah ke bawah dari O. Titiknya di Kuadran III.', 1) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F03', 'final-challenge', 'mc', 'koordinat', 'Titik pada sumbu Y yang berjarak 5 satuan di bawah titik asal adalah ...', '{"options": ["(0, −5)", "(−5, 0)", "(5, 0)", "(0, 5)"]}'::jsonb, '0'::jsonb, 'Pada sumbu Y, x = 0. Di bawah titik asal berarti y negatif: (0, −5).', 2) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F04', 'final-challenge', 'tf', 'titik-garis', 'Titik (−1, −1) terletak pada garis y = 3x + 2.', '{}'::jsonb, 'true'::jsonb, '3(−1) + 2 = −1, sama dengan y-nya. Jadi titik tersebut terletak pada garis.', 3) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F05', 'final-challenge', 'mc', 'titik-garis', 'Garis melalui (0, 1) dan (1, 3). Titik berikut terletak pada garis tersebut, KECUALI ...', '{"options": ["(2, 5)", "(3, 7)", "(−1, −1)", "(4, 8)"]}'::jsonb, '3'::jsonb, 'Garisnya y = 2x + 1. Untuk x = 4: y = 9, bukan 8. Titik lain memenuhi persamaan.', 4) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F06', 'final-challenge', 'num', 'gradien', 'Gradien garis yang melalui (−4, −1) dan (2, 2) adalah ...', '{}'::jsonb, '"1/2"'::jsonb, 'm = (2 − (−1))/(2 − (−4)) = 3/6 = 1/2.', 5) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F07', 'final-challenge', 'num', 'gradien', 'Gradien garis yang melalui (5, −2) dan (1, 6) adalah ...', '{}'::jsonb, '"-2"'::jsonb, 'm = (6 − (−2))/(1 − 5) = 8/(−4) = −2.', 6) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F08', 'final-challenge', 'mc', 'gradien', 'Gradien garis yang melalui (3, −1) dan (3, 4) adalah ...', '{"options": ["tidak terdefinisi", "0", "5", "1/5"]}'::jsonb, '0'::jsonb, 'x₂ − x₁ = 3 − 3 = 0. Pembagian dengan nol tidak terdefinisi; garisnya vertikal x = 3.', 7) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F09', 'final-challenge', 'num', 'gradien', 'Gradien garis 5x + 2y − 10 = 0 adalah ...', '{}'::jsonb, '"-5/2"'::jsonb, 'm = −a/b = −5/2.', 8) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F10', 'final-challenge', 'mc', 'grafik', 'Perhatikan grafik. Gradien garis tersebut adalah ...', '{"options": ["1/2", "2", "−1/2", "−2"], "graph": {"range": 6, "lines": [{"m": 0.5, "c": -2}], "points": [{"x": 0, "y": -2, "label": "(0, −2)"}, {"x": 4, "y": 0, "label": "(4, 0)"}]}}'::jsonb, '0'::jsonb, 'm = (0 − (−2))/(4 − 0) = 2/4 = 1/2.', 9) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F11', 'final-challenge', 'mc', 'persamaan', 'Persamaan garis bergradien 3 yang memotong sumbu Y di (0, −2) adalah ...', '{"options": ["y = 3x − 2", "y = −2x + 3", "y = 3x + 2", "y = −3x − 2"]}'::jsonb, '0'::jsonb, 'y = mx + c dengan m = 3 dan c = −2 → y = 3x − 2.', 10) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F12', 'final-challenge', 'mc', 'persamaan', 'Bentuk umum dari y = 2x − 5 adalah ...', '{"options": ["2x − y − 5 = 0", "2x + y − 5 = 0", "x − 2y − 5 = 0", "2x − y + 5 = 0"]}'::jsonb, '0'::jsonb, 'Pindahkan y ke ruas kanan: 0 = 2x − y − 5, atau 2x − y − 5 = 0.', 11) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F13', 'final-challenge', 'mc', 'grafik', 'Perhatikan grafik. Persamaan garis tersebut adalah ...', '{"options": ["y = −2x + 4", "y = 2x + 4", "y = −2x + 2", "y = −(1/2)x + 4"], "graph": {"range": 6, "lines": [{"m": -2, "c": 4}], "points": [{"x": 0, "y": 4, "label": "(0, 4)"}, {"x": 2, "y": 0, "label": "(2, 0)"}]}}'::jsonb, '0'::jsonb, 'c = 4 (titik potong sumbu Y). m = (0 − 4)/(2 − 0) = −2. Jadi y = −2x + 4.', 12) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F14', 'final-challenge', 'num', 'persamaan', 'Garis y = −3x + 9 memotong sumbu X di titik (a, 0). Nilai a adalah ...', '{}'::jsonb, '"3"'::jsonb, '0 = −3x + 9 → 3x = 9 → x = 3.', 13) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F15', 'final-challenge', 'line', 'menentukan', 'Tentukan persamaan garis bergradien 4 yang melalui (1, −2).', '{}'::jsonb, '{"m": "4", "c": "-6"}'::jsonb, 'y − (−2) = 4(x − 1) → y + 2 = 4x − 4 → y = 4x − 6.', 14) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F16', 'final-challenge', 'line', 'menentukan', 'Tentukan persamaan garis yang melalui (−2, 1) dan (2, 9).', '{}'::jsonb, '{"m": "2", "c": "5"}'::jsonb, 'm = (9 − 1)/(2 − (−2)) = 8/4 = 2. y − 1 = 2(x + 2) → y = 2x + 5.', 15) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F17', 'final-challenge', 'line', 'menentukan', 'Tentukan persamaan garis yang melalui titik pusat dan titik (4, −2).', '{}'::jsonb, '{"m": "-1/2", "c": "0"}'::jsonb, 'm = (−2 − 0)/(4 − 0) = −1/2. Melalui titik pusat → c = 0. y = −(1/2)x.', 16) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F18', 'final-challenge', 'line', 'menentukan', 'Tentukan persamaan garis yang melalui (6, 0) dan (0, 3).', '{}'::jsonb, '{"m": "-1/2", "c": "3"}'::jsonb, 'm = (3 − 0)/(0 − 6) = −1/2. Titik (0, 3) → c = 3. y = −(1/2)x + 3.', 17) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F19', 'final-challenge', 'mc', 'hubungan', 'Persamaan garis yang melalui (2, 5) dan sejajar dengan y = −x + 1 adalah ...', '{"options": ["y = −x + 7", "y = x + 3", "y = −x + 3", "y = −x + 5"]}'::jsonb, '0'::jsonb, 'Sejajar → m = −1. y − 5 = −(x − 2) → y = −x + 7. (y = x + 3 memang melalui (2, 5), tetapi gradiennya 1, tidak sejajar.)', 18) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F20', 'final-challenge', 'num', 'hubungan', 'Garis g tegak lurus dengan garis 3x − y + 2 = 0. Gradien garis g adalah ...', '{}'::jsonb, '"-1/3"'::jsonb, 'Gradien 3x − y + 2 = 0 adalah −3/(−1) = 3. Garis tegak lurusnya bergradien −1/3.', 19) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F21', 'final-challenge', 'line', 'hubungan', 'Tentukan persamaan garis yang melalui (3, 1) dan tegak lurus dengan y = 3x − 4.', '{}'::jsonb, '{"m": "-1/3", "c": "2"}'::jsonb, 'm = −1/3. y − 1 = −(1/3)(x − 3) → y − 1 = −(1/3)x + 1 → y = −(1/3)x + 2.', 20) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F22', 'final-challenge', 'num', 'hubungan', 'Garis y = ax + 2 sejajar dengan garis y = 4x − 1. Nilai a adalah ...', '{}'::jsonb, '"4"'::jsonb, 'Sejajar → gradiennya sama, sehingga a = 4.', 21) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F23', 'final-challenge', 'num', 'kehidupan', 'Sebuah tangki berisi 200 liter air dan bocor 8 liter setiap jam. Setelah berapa jam tangki kosong?', '{}'::jsonb, '"25"'::jsonb, 'Model y = −8x + 200. Tangki kosong saat y = 0: 8x = 200 → x = 25 jam. Gradien negatif berarti air berkurang.', 22) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
insert into public.quiz_questions (id, quiz_slug, qtype, topic, prompt, payload, answer, explanation, position) values ('F24', 'final-challenge', 'num', 'kehidupan', 'Harga 4 kg beras Rp56.000 dan 10 kg Rp140.000 (hubungan linear). Berapa rupiah harga 7 kg beras? (angka saja)', '{}'::jsonb, '"98000"'::jsonb, 'm = (140.000 − 56.000)/(10 − 4) = 84.000/6 = 14.000 per kg, y = 14.000x. Untuk 7 kg: 98.000.', 23) on conflict (id) do update set quiz_slug = excluded.quiz_slug, qtype = excluded.qtype, topic = excluded.topic, prompt = excluded.prompt, payload = excluded.payload, answer = excluded.answer, explanation = excluded.explanation, position = excluded.position;
